/**
 * novelty-cases.ts — 写侧折叠尺的夹具(记忆经济 M4)。
 *
 * 每一轮都用 `buildTurnCapture` 真的会写出来的那个格式(`User: …\nButler: …`)。这不是
 * 讲究:管家的回复**一起被写进条目里**,正是它让「明天的会」和「后天的会」分得开
 * —— 只拿用户那半句去比,`③` 那条用例会当场误折。夹具照抄生产的形状,才量得到生产。
 *
 * 四条用例分两类:
 *
 *   - `①` `③` 各自单点:一条量该折的折不折,一条量该留的会不会被误折。
 *   - `②` `④` 是**陷阱与控制组**:`②` 那条 `好的` 在单向覆盖率下会被长回合整个吞掉
 *     (它的词全在长回合里),双向覆盖必须把它救回来;`④` 全是新东西,一条都不许折。
 *
 * `③` 的存在理由值得单说:它是这把刀**最容易错的地方** —— 词面重合极高、意思完全不同。
 * 它没被误折靠的是回复里那两个具体值(10 点 / 3 点半),而不是靠阈值调得好。真要有一天
 * 它红了,该改的多半是「比什么」,不是把 0.8 往上抬。
 */

import type { NoveltyCase } from '../../src/novelty-benchmark.js'

/** 生产 capture 的渲染格式。夹具里手写会漂,统一走这一个。 */
const turn = (user: string, butler: string): string => `User: ${user}\nButler: ${butler}`

